/* The live Mac connection is intentionally separate from the browser-only demo. */
(()=>{
if(location.protocol==='http:'&&!['localhost','127.0.0.1'].includes(location.hostname)){location.replace('https:'+location.href.slice(location.protocol.length));return}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const basename=s=>String(s||'').split('/').pop();
let csrf='',authenticated=false,latest=[];
async function api(path,body){const response=await fetch('/api/v1/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRFToken':csrf}:{},body:body?JSON.stringify(body):undefined});const result=await response.json().catch(()=>({detail:'서버 응답을 읽을 수 없습니다.'}));if(!response.ok)throw new Error(result.detail||result.error||`HTTP ${response.status}`);return result}
async function session(){try{const s=await api('auth/session/');csrf=s.csrf;authenticated=s.authenticated;document.getElementById('agent-login').hidden=authenticated;document.getElementById('agent-live').hidden=!authenticated;document.getElementById('agent-account').textContent=s.username?`${s.username} 계정`:' ';if(authenticated)await refresh()}catch(e){document.getElementById('agent-login-error').textContent=e.message}}
function updateNotice(){const active=document.getElementById('connection').classList.contains('active');document.getElementById('reset-demo').hidden=active;document.querySelector('.demo-notice span:nth-of-type(2)').textContent=active?'이 화면에서 승인한 명령은 연결된 Mac의 실제 파일을 변경할 수 있습니다. 다른 화면은 시연 데이터입니다.':'파일·기기·처리 기록은 이 브라우저에만 저장됩니다. 실제 파일은 변경되지 않습니다.'}
function assetHTML(a,link){const run=a.run||{},plan=a.plan||{},name=basename(a.name||a.original||a.path)||a.id,projects=link.snapshot.catalog||[];const choices=(run.candidates?.length?projects.filter(p=>run.candidates.includes(p.id)):projects);const options=choices.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');const reasons=(a.why||[]).slice(0,4).map(x=>`<p>${esc(x)}</p>`).join('');const canApprove=['file','archive'].includes(plan.action)&&!a.archived;return `<article class="agent-asset" data-asset="${esc(a.id)}"><div class="review-card-header"><h3>${esc(name)}</h3><span class="chip ${run.status==='waiting_user'?'other':''}">${esc(a.archived?'이동됨':run.status==='waiting_user'?'질문 대기':plan.action==='file'?'승인 대기':plan.action||'판단 중')}</span></div>${reasons||`<p>${esc(run.question||'판단 근거를 기다리는 중입니다.')}</p>`}${plan.target?`<p>계획: ${esc(plan.action)} → ${esc(basename(plan.target))}</p>`:''}${run.question?`<p><b>질문:</b> ${esc(run.question)}</p>`:''}<div class="actions">${run.status==='waiting_user'&&!a.archived&&options?`<select class="agent-project" aria-label="대상 프로젝트">${options}</select><button class="ghost" data-agent-action="answer">답변 보내기</button>`:''}${canApprove?`<button class="primary" data-agent-action="approve">계획 승인</button>`:''}${!a.archived&&!a.keep?`<button class="ghost" data-agent-action="keep">그대로 두기</button>`:''}${a.archived?`<button class="ghost" data-agent-action="undo">이동 되돌리기</button>`:''}</div></article>`}
function linkHTML(link){const s=link.snapshot||{},assets=s.assets||[],trash=s.trashed||[],commands=link.commands||[];return `<section class="agent-state" data-link="${esc(link.id)}"><div class="review-card-header"><h2>${esc(link.label)}</h2><span class="agent-status ${link.connected?'online':''}">${link.connected?'연결됨':'연결 대기'}${link.last_seen_at?' · 마지막 동기화 '+esc(new Date(link.last_seen_at).toLocaleString('ko-KR')):''}</span></div><p>${link.connected?'Mac 에이전트 상태를 표시합니다. 승인한 계획만 실행기로 전달됩니다.':'Mac 에이전트와 브리지 프로그램을 실행하면 여기에 상태가 나타납니다.'}</p><div class="agent-assets">${assets.length?assets.map(a=>assetHTML(a,link)).join(''):'<div class="empty">전송된 파일 상태가 없습니다.</div>'}</div>${trash.length?`<div class="agent-trash"><h3>Mac 휴지통으로 이동한 설치 파일</h3>${trash.map(t=>`<div class="journal-row"><span>${esc(basename(t.name||t.path||t.trash))}</span><button class="ghost" data-trash-index="${Number(t.i)}">복구 요청</button></div>`).join('')}</div>`:''}${commands.length?`<div class="agent-trash"><h3>최근 명령</h3>${commands.slice(0,5).map(c=>`<div class="agent-command ${c.status==='failed'?'failed':''}">${esc(c.action)} · ${esc(c.status)}${c.status==='failed'?' · '+esc(c.result?.result||'실행 실패'):''}</div>`).join('')}</div>`:''}</section>`}
async function refresh(){if(!authenticated)return;try{const r=await api('agent/status/');latest=r.links||[];document.getElementById('agent-links').innerHTML=latest.length?latest.map(linkHTML).join(''):'<div class="empty">연결된 Mac이 없습니다. 서버에서 브리지 토큰을 발급하고 Mac 브리지를 실행해 주세요.</div>'}catch(e){document.getElementById('agent-links').innerHTML=`<div class="empty">연결 상태를 읽지 못했습니다: ${esc(e.message)}</div>`}}
document.getElementById('agent-login-form').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.target);try{await api('auth/login/',{username:data.get('username'),password:data.get('password')});e.target.reset();document.getElementById('agent-login-error').textContent='';await session()}catch(err){document.getElementById('agent-login-error').textContent=err.message}});
document.getElementById('agent-logout').addEventListener('click',async()=>{try{await api('auth/logout/',{});authenticated=false;latest=[];await session()}catch(e){alert(e.message)}});
document.getElementById('agent-links').addEventListener('click',async e=>{const b=e.target.closest('[data-agent-action],[data-trash-index]');if(!b)return;const section=b.closest('[data-link]'),link=latest.find(x=>x.id===section.dataset.link);if(!link?.connected){alert('Mac 브리지가 연결된 뒤 요청해 주세요.');return}const card=b.closest('[data-asset]'),asset=card&&link.snapshot.assets.find(x=>x.id===card.dataset.asset),action=b.dataset.agentAction||'restore_trashed';let body={link_id:link.id,action},message='';if(action==='restore_trashed'){body.trash_index=Number(b.dataset.trashIndex);message='Mac 휴지통의 파일을 원래 자리로 복구하시겠습니까?'}else{body.asset_id=asset.id;const name=basename(asset.name||asset.original||asset.path);if(action==='answer'){body.project_id=card.querySelector('.agent-project').value;const project=link.snapshot.catalog.find(x=>x.id===body.project_id);message=`${name}의 프로젝트를 ${project?.name||body.project_id}(으)로 답변하시겠습니까? 이 답변은 Mac의 _project.md 지침을 수정할 수 있지만 파일 이동은 별도 승인입니다.`}else if(action==='approve'){message=`${name}을(를) ${basename(asset.plan.target)}(으)로 실제 이동하시겠습니까? 에이전트가 현재 계획과 해시를 다시 확인합니다.`}else if(action==='undo'){message=`${name}의 실제 파일 이동을 되돌리시겠습니까?`}else message=`${name}을(를) 현재 위치에 그대로 두시겠습니까?`}
if(!confirm(message))return;try{await api('agent/commands/',body);await refresh();alert('요청을 등록했습니다. Mac 브리지가 실행하면 결과가 표시됩니다.')}catch(err){alert(err.message)}});
document.addEventListener('click',e=>{if(e.target.closest('[data-page]'))setTimeout(()=>{updateNotice();if(authenticated&&document.getElementById('connection').classList.contains('active'))refresh()},0)});window.addEventListener('hashchange',updateNotice);updateNotice();session();setInterval(()=>{if(authenticated&&document.getElementById('connection').classList.contains('active'))refresh()},5000);
})();
